const businessRoutes={connections:['sources','accounts','deployment','collectors','collection','protection','remote','sync'],assets:['sync','permissions','sensitive','relations','risk','trust'],detection:['baseline','vulnerabilities','behavior','passwords','rules','learning','templates','allowlists'],threats:['paths','behavior','search','honeypots'],response:['policies','allowlist','history'],reports:['templates','library'],work:['schedules','notifications','recipients','health'],admin:['profile','accounts','mfa','users','roles','resources','audit','integrations','system','license','settings','services','diagnostics','install']};
const internalCopy=/AD-F-\d{3}|产品验收|覆盖说明|规划说明|固定夹具|后续验收|safeReplay|demo-epoch|未实现|实现说明|独立验收|原型没有|本原型|夹具|synthetic_|demonstration-only|EXTERNAL_EFFECT|真实外部副作用|通用recover/;
for(const [section,pages] of Object.entries(businessRoutes))await test('Discoverable '+section+' business pages without development commentary',async p=>{await nav(p,section);for(const sub of pages){const route=section+'/'+sub;const entry=p.locator(`a[href="#/${route}"]`).first();assert(await entry.count(),'Missing discoverable sub-navigation: '+route);await entry.click();await waitFor(async()=>await p.locator('.section-nav a[aria-current="page"]').getAttribute('href')==='#/'+route);const body=await p.locator('main').innerText();assert(!internalCopy.test(body),'Development commentary on '+route+': '+body.match(internalCopy));assert(!/敬请期待|功能建设中|即将上线/.test(body),'Placeholder on '+route);assert((await p.locator('main table,main form,main dl,main .chart,main input,main select').count())>0,'No business content on '+route);await nav(p,section);}});
await test('All main product pages omit review and implementation commentary',async p=>{for(const section of ['overview',...Object.keys(businessRoutes)]){await nav(p,section);const body=await p.locator('main').innerText();assert(!internalCopy.test(body),'Development commentary on '+section+': '+body.match(internalCopy));}});
await test('Narrow-screen business navigation and key domains remain within viewport',async p=>{for(const route of ['connections/collectors','detection/rules','threats/paths','work/notifications','admin/users','admin/license']){await nav(p,route);assert(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'Page overflow: '+route);}await nav(p,'detection/rules');await p.screenshot({path:path.join(OUT,'05-mobile-rules.png'),fullPage:true});},{mobile:true});
async function biz(p,route,verb,id='',intent=null){const selector=`[data-action="biz-action"][data-page="${route}"][data-verb="${verb}"][data-id="${id}"]${intent?`[data-intent="${intent}"]`:''}`;await p.locator(selector).first().click();}
async function bizConfirm(p){await p.locator('#biz-confirm-check').check();await confirm(p);}
async function cleanDialog(p){assert(!internalCopy.test(await p.locator('#dialog').innerText()),'Development commentary in business dialog');}
